&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;9qjra&quot; data-offset-key=&quot;2ampl-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;2ampl-0-0&quot;&gt;&lt;span data-offset-key=&quot;2ampl-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Solving hard distributed systems problems at scale.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;9qjra&quot; data-offset-key=&quot;5ll9i-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;5ll9i-0-0&quot;&gt;&lt;span data-offset-key=&quot;5ll9i-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Maintaining, updating and improving existing code and dependencies while ensuring automated test coverage.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;9qjra&quot; data-offset-key=&quot;dcus5-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;dcus5-0-0&quot;&gt;&lt;span data-offset-key=&quot;dcus5-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Engaging with multiple public GitHub repositories and community forums.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;9qjra&quot; data-offset-key=&quot;pujn-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;pujn-0-0&quot;&gt;&lt;span data-offset-key=&quot;pujn-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Providing Pull Request reviews and guidance to your peers.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
