&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;9qjra&quot; data-offset-key=&quot;20lte-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;20lte-0-0&quot;&gt;&lt;span data-offset-key=&quot;20lte-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Working &lt;/span&gt;&lt;/span&gt;&lt;span id=&quot;popover-trigger-:r14:&quot; class=&quot;chakra-text css-8zk7oi&quot;&gt;&lt;span data-offset-key=&quot;20lte-1-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;together&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span data-offset-key=&quot;20lte-2-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt; with the support organization to help our customers, which will also include participating in an on-call rotation.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
